// Lee la pregunta enviada por el backend: { "pregunta": "..." }
const body = $input.first().json.body || {};
const pregunta = String(body.pregunta ?? '').trim();
return [{ json: { pregunta, valida: pregunta.length >= 3 && pregunta.length <= 1000 } }];

// Filtra los fragmentos recuperados de Qdrant por similitud, neutraliza instrucciones
// maliciosas y construye el contexto delimitado y la lista de fuentes.
const ADVERTENCIA = "Información con fines educativos basada en los documentos de la biblioteca de NutriGuide. No constituye diagnóstico, tratamiento ni dieta clínica personalizada.";
const SIN_INFO = "No encontré información suficiente en los documentos educativos de NutriGuide para responder tu pregunta de forma verificada. Prueba a reformularla o consulta sobre alimentos, nutrientes, hidratación o hábitos alimentarios.";
let minimo = 0.55;
try { minimo = Number($env.RAG_MIN_SIMILARITY) || minimo; } catch (e) { /* sin acceso a $env */ }

const { pregunta, valida } = $('Validar pregunta').first().json;
if (!valida) {
  return [{ json: { hayContexto: false, codigo: 400,
    cuerpo: { exito: false, mensaje: 'La pregunta debe tener entre 3 y 1000 caracteres.' } } }];
}

let sinClave = false;
try { sinClave = !String($env.GEMINI_API_KEY || '').trim(); } catch (e) { /* sin acceso a $env */ }
if (sinClave) {
  return [{ json: { hayContexto: false, valido: false, codigo: 503,
    cuerpo: { exito: false, mensaje: 'El asistente no tiene configurada la clave de Google Gemini (GEMINI_API_KEY en IA/.env).' } } }];
}

const items = $input.all();
const conError = items.find((i) => i.json.error);
if (conError) {
  const mensaje = String(conError.json.error?.message ?? conError.json.error);
  const detalle = JSON.stringify(conError.json.error ?? '');
  if (/api.?key|unauthenticated|permission|forbidden|credential|\b40[13]\b/i.test(mensaje + ' ' + detalle)) {
    return [{ json: { hayContexto: false, codigo: 503,
      cuerpo: { exito: false, mensaje: 'La clave de Google Gemini no es válida o fue desactivada. Configura una nueva GEMINI_API_KEY en IA/.env.' } } }];
  }
  // Solo si la colección aún no existe (no hay documentos indexados) se responde "sin información"
  const sinColeccion = /collection|colecci/i.test(mensaje + ' ' + detalle) && /not found|doesn.?t exist|no existe/i.test(mensaje + ' ' + detalle);
  if (!sinColeccion) {
    return [{ json: { hayContexto: false, codigo: 502,
      cuerpo: { exito: false, mensaje: 'No fue posible consultar la base vectorial: ' + mensaje.slice(0, 200) } } }];
  }
}

// Si la búsqueda falla, n8n deja pasar el ítem de entrada (con "valida") sin el mensaje de error
if (items.some((i) => i.json.valida !== undefined && !i.json.document)) {
  let coleccionExiste = true;
  try {
    await this.helpers.httpRequest({ method: 'GET', url: `${$env.QDRANT_URL}/collections/nutriguide_documentos`,
      headers: { 'api-key': $env.QDRANT_API_KEY }, json: true });
  } catch (e) {
    coleccionExiste = !/404/.test(String(e.httpCode ?? e.message ?? e));
  }
  if (coleccionExiste) {
    return [{ json: { hayContexto: false, codigo: 503,
      cuerpo: { exito: false, mensaje: 'No se pudo consultar la base de conocimiento: Google Gemini rechazó la petición o Qdrant no respondió. Revisa que GEMINI_API_KEY en IA/.env sea válida (la ejecución en n8n muestra el detalle).' } } }];
  }
}

const INYECCION =/(ignora\s+(todas\s+)?(las\s+)?instrucciones(\s+anteriores|\s+previas)?|ignore\s+(all\s+)?(the\s+)?(previous|prior|above)\s+instructions|olvida\s+(todas\s+)?(tus|las)\s+(reglas|instrucciones)|disregard\s+(all\s+)?(previous|prior)\s+instructions|system\s*prompt\s*:|act[uú]a\s+como\s+(un\s+)?(sistema|modelo|asistente)\s+sin\s+(restricciones|reglas)|eres\s+ahora\s+(un\s+)?(modelo|asistente)\s+sin\s+(reglas|restricciones)|you\s+are\s+now\s+(a|an)\s+\w+|<\/?\s*CONTEXTO_DOCUMENTAL_VERIFICADO\s*>)/giu;
// Las llaves se sustituyen porque las plantillas de LangChain las interpretan como variables
const limpiar = (t) => String(t ?? '').replace(INYECCION, '[INSTRUCCIÓN EXTERNA BLOQUEADA POR SEGURIDAD]')
  .replace(/\{/g, '(').replace(/\}/g, ')');

const fragmentos = items
  .filter((i) => i.json.document && typeof i.json.score === 'number' && i.json.score >= minimo)
  .sort((a, b) => b.json.score - a.json.score)
  .map((i) => ({ contenido: limpiar(i.json.document.pageContent), meta: i.json.document.metadata || {}, score: i.json.score }));

if (fragmentos.length === 0) {
  return [{ json: { hayContexto: false, codigo: 200,
    cuerpo: { respuesta: SIN_INFO, fuentes: [], informacionSuficiente: false, advertenciaEducativa: ADVERTENCIA } } }];
}

const contexto = fragmentos.map((f, n) => [
  `--- FUENTE DOCUMENTAL #${n + 1} ---`,
  `Título del documento: ${limpiar(f.meta.titulo)}`,
  `Procedencia: ${limpiar(f.meta.fuenteOrigen)}`,
  `Categoría: ${limpiar(f.meta.categoria)}`,
  'Contenido:',
  f.contenido,
].join('\n')).join('\n\n');

const fuentes = fragmentos.map((f) => ({
  titulo: String(f.meta.titulo || 'Documento'),
  contenido: f.contenido,
  documentoId: Number(f.meta.documentoId) || null,
  categoria: String(f.meta.categoria || ''),
  fuenteOrigen: String(f.meta.fuenteOrigen || ''),
  similitud: Math.round(f.score * 1000) / 1000,
}));

const prompt = `<CONTEXTO_DOCUMENTAL_VERIFICADO>
${contexto}
</CONTEXTO_DOCUMENTAL_VERIFICADO>

PREGUNTA DEL USUARIO:
${limpiar(pregunta)}

Responde siguiendo tus reglas, usando solo el contexto anterior.`;

return [{ json: { hayContexto: true, prompt, fuentes } }];

// Arma la respuesta final para el backend: { respuesta, fuentes, informacionSuficiente, advertenciaEducativa }
const ADVERTENCIA = "Información con fines educativos basada en los documentos de la biblioteca de NutriGuide. No constituye diagnóstico, tratamiento ni dieta clínica personalizada.";
const SIN_INFO = "No encontré información suficiente en los documentos educativos de NutriGuide para responder tu pregunta de forma verificada. Prueba a reformularla o consulta sobre alimentos, nutrientes, hidratación o hábitos alimentarios.";
const MARCA = '[SIN_INFORMACION]';
const r = $input.first().json;
const { fuentes } = $('Preparar contexto').first().json;

if (r.error) {
  const mensaje = String(r.error?.message ?? r.error);
  return [{ json: { codigo: 502, cuerpo: { exito: false, mensaje: 'El modelo de lenguaje no respondió: ' + mensaje.slice(0, 200) } } }];
}
let texto = String(r.text ?? r.output ?? r.response ?? '').trim();
if (!texto) {
  return [{ json: { codigo: 502, cuerpo: { exito: false, mensaje: 'El modelo de lenguaje devolvió una respuesta vacía.' } } }];
}
if (texto.startsWith(MARCA)) {
  texto = texto.slice(MARCA.length).trim() || SIN_INFO;
  return [{ json: { codigo: 200, cuerpo: { respuesta: texto, fuentes: [], informacionSuficiente: false, advertenciaEducativa: ADVERTENCIA } } }];
}
return [{ json: { codigo: 200, cuerpo: { respuesta: texto, fuentes, informacionSuficiente: true, advertenciaEducativa: ADVERTENCIA } } }];

// Documento enviado por el backend: { documentoId, titulo, categoria, fuenteOrigen, contenido }
const b = $input.first().json.body || {};
const documentoId = String(b.documentoId ?? '').trim();
const contenido = String(b.contenido ?? '').trim();
let sinClave = false;
try { sinClave = !String($env.GEMINI_API_KEY || '').trim(); } catch (e) { /* sin acceso a $env */ }
if (sinClave) {
  return [{ json: { valido: false, codigo: 503,
    cuerpo: { exito: false, mensaje: 'El asistente no tiene configurada la clave de Google Gemini (GEMINI_API_KEY en IA/.env).' } } }];
}
if (!/^\d+$/.test(documentoId) || contenido.length < 20) {
  return [{ json: { valido: false, codigo: 400,
    cuerpo: { exito: false, mensaje: 'Se requieren un documentoId numérico y al menos 20 caracteres de contenido.' } } }];
}
return [{ json: {
  valido: true,
  documentoId,
  titulo: String(b.titulo ?? 'Documento').slice(0, 255),
  categoria: String(b.categoria ?? '').slice(0, 100),
  fuenteOrigen: String(b.fuenteOrigen ?? '').slice(0, 255),
  contenido,
} }];

// Cada ítem de salida del nodo de inserción es un fragmento guardado en Qdrant
const items = $input.all();
const conError = items.find((i) => i.json.error);
const { documentoId } = $('Preparar documento').first().json;
if (conError) {
  const mensaje = String(conError.json.error?.message ?? conError.json.error);
  const detalle = JSON.stringify(conError.json.error ?? '');
  if (/api.?key|unauthenticated|permission|forbidden|credential|\b40[13]\b/i.test(mensaje + ' ' + detalle)) {
    return [{ json: { codigo: 503, cuerpo: { exito: false, mensaje: 'La clave de Google Gemini no es válida o fue desactivada. Configura una nueva GEMINI_API_KEY en IA/.env.' } } }];
  }
  return [{ json: { codigo: 502, cuerpo: { exito: false, mensaje: 'No se pudo indexar el documento: ' + mensaje.slice(0, 300) } } }];
}
return [{ json: { codigo: 200, cuerpo: { documentoId: Number(documentoId), fragmentos: items.length, coleccion: "nutriguide_documentos" } } }];

// { documentoId } del documento cuyos fragmentos se borran de Qdrant
const b = $input.first().json.body || {};
const documentoId = String(b.documentoId ?? '').trim();
if (!/^\d+$/.test(documentoId)) {
  return [{ json: { valido: false, codigo: 400, cuerpo: { exito: false, mensaje: 'Se requiere un documentoId numérico.' } } }];
}
return [{ json: { valido: true, documentoId } }];

// Un 404 significa que la colección aún no existe: no hay nada que borrar
const r = $input.first().json;
const { documentoId } = $('Validar eliminación').first().json;
if (r.error) {
  const mensaje = String(r.error?.message ?? r.error);
  if (!/404|not found|doesn.?t exist/i.test(mensaje)) {
    return [{ json: { codigo: 502, cuerpo: { exito: false, mensaje: 'No se pudieron borrar los fragmentos: ' + mensaje.slice(0, 200) } } }];
  }
}
return [{ json: { codigo: 200, cuerpo: { documentoId: Number(documentoId), eliminado: true } } }];
